def step(context):
    world = context['inputs']['observations'][0]['payload']
    decisions = []
    for conf in world['conferences']['conferences']:
        scored = []
        for paper in conf['submitted_papers']:
            reviews = conf['reviews'].get(paper['id'], [])
            if not reviews:
                raise ValueError('actual submitted paper has no reviews')
            score = sum(r['overall_score'] for r in reviews) / len(reviews)
            scored.append((paper['id'], score))
        scored.sort(key=lambda pair: pair[1], reverse=True)
        rates = context['parameters'].get('annual_rates')
        rate = rates[context['period'] - 1] if rates is not None else conf['acceptance_rate']
        slots = max(1, round(len(scored) * rate))
        for index, (paper_id, score) in enumerate(scored):
            decisions.append({'payload': {'paper_id': paper_id, 'conference_id': conf['conference_id'],
                'final_score': score, 'decision': 'accept' if index < slots else 'reject'}})
    if not decisions:
        decisions = [{'payload': {'empty_cycle': True}}]
    return {'outputs': {'next': [{'payload': {'year': context['period']}}],
        'world': [{'payload': world}], 'decisions': decisions},
        'state': {'cycles': context['state'].get('cycles', 0) + 1}}

def step(context):
    world = context['inputs']['observations'][0]['payload']
    acceptance_cost = context['parameters']['acceptance_cost']
    verdicts = []
    for conf in world['conferences']['conferences']:
        for paper in conf['submitted_papers']:
            reviews = conf['reviews'].get(paper['id'], [])
            mean_score = sum(review['overall_score'] for review in reviews) / len(reviews) if reviews else 0.0
            decision = 'accept' if mean_score > acceptance_cost else 'reject'
            verdicts.append({'payload': {'paper_id': paper['id'], 'conference_id': conf['conference_id'], 'decision': decision, 'final_score': mean_score}, 'actor_ids': [], 'artifact_ids': []})
    if not verdicts:
        verdicts = [{'payload': {'empty_cycle': True}, 'actor_ids': [], 'artifact_ids': []}]
    completion = [{'payload': {'year': context['period']}, 'actor_ids': [], 'artifact_ids': []}]
    return {'outputs': {'verdicts': verdicts, 'completion': completion}, 'state': {}}

def step(context):
    world = context['inputs']['observations'][0]['payload']
    cost = context['parameters']['publication_cost']
    offers = []
    for conf in world['conferences']['conferences']:
        for paper in conf['submitted_papers']:
            reviews = conf['reviews'].get(paper['id'], [])
            mean_score = sum(review['overall_score'] for review in reviews) / len(reviews) if reviews else 0.0
            offers.append({'paper_id': paper['id'], 'conference_id': conf['conference_id'], 'review_mean': mean_score, 'loss_increment': cost - mean_score})
    packet = {'payload': {'year': context['period'], 'offers': offers}, 'actor_ids': [], 'artifact_ids': []}
    return {'outputs': {'offers': [packet]}, 'state': {}}

def step(context):
    packet = context['inputs']['proposals'][0]['payload']
    verdicts = []
    for offer in packet['offers']:
        decision = 'accept' if offer['loss_increment'] < 0.0 else 'reject'
        verdicts.append({'payload': {'paper_id': offer['paper_id'], 'conference_id': offer['conference_id'], 'decision': decision, 'final_score': offer['review_mean']}, 'actor_ids': [], 'artifact_ids': []})
    if not verdicts:
        verdicts = [{'payload': {'empty_cycle': True}, 'actor_ids': [], 'artifact_ids': []}]
    completion = [{'payload': {'year': packet['year']}, 'actor_ids': [], 'artifact_ids': []}]
    return {'outputs': {'verdicts': verdicts, 'completion': completion}, 'state': {}}

